USE `{{DB_NAME}}`;
CREATE TABLE IF NOT EXISTS loginNotices (id TINYINT NOT NULL PRIMARY KEY, enabled TINYINT NOT NULL DEFAULT 0, noticeText TEXT CHARACTER SET utf8mb4 NOT NULL, revision CHAR(64) CHARACTER SET ascii NOT NULL, updatedBy VARCHAR(255) NOT NULL, updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
